    const weg = await admin.anfrage("DELETE", `/api/admin/entwicklung/${tp.id}/eintraege?art=flaeche&id=${pfEintrag.id}`);
    pruefe([200, 204].includes(weg.status), "Verknüpfung der Akquise-Fläche wieder gelöst", weg.status);
  }
